/* ── HERO ── */
.hero { position: relative; min-height: 100svh; display: flex; flex-direction: column; justify-content: flex-end; padding: 0 var(--pad) clamp(1.8rem, 4vh, 3.5rem); overflow: hidden; }
.hero-label { position: absolute; z-index: 3; top: 6rem; left: var(--pad); text-transform: uppercase; color: var(--dim); }
